                gaveta[i] = (chave, valor)
                return
        gaveta.append((chave, valor))
        self._tamanho += 1

    def pegar(self, chave, padrao=None):
        for k, v in self._gaveta(chave):
            if k == chave:
                return v
        return padrao

    def __len__(self):
        return self._tamanho


